import { test, expect, type Page } from '@playwright/test'

// C17 — the cold path generated by a REAL model, on camera. Opt-in only
// (npm run e2e:live + OPENROUTER_API_KEY in the local .env): real network,
// real cost, non-deterministic output. Asserts are structural on purpose —
// a chain compiled from a live response, guard filtering, vocabulary held —
// never exact ops; pretending a model is deterministic would fake the proof.

const EV = 'e2e/evidence-carbon'
const KEY = process.env.OPENROUTER_API_KEY
const ENABLED = process.env.LIVE_LLM === '1' && !!KEY

interface AuditEntry {
  kind: string
  detail: string
}
interface Exchange {
  route: string
  model: string
  persona: unknown
  returned?: unknown
  error?: string
}

const audit = (page: Page) =>
  page.evaluate(() => ((window as unknown as { __audit?: AuditEntry[] }).__audit ?? []) as AuditEntry[])
const exchanges = (page: Page) =>
  page.evaluate(() => ((window as unknown as { __coldpath?: Exchange[] }).__coldpath ?? []) as Exchange[])

test('live cold path: a real model proposes the ops during navigation, guard-checked', async ({ page }) => {
  test.skip(!ENABLED, 'opt-in: npm run e2e:live with OPENROUTER_API_KEY in .env')

  // config must exist before the page module reads it
  await page.context().addInitScript(
    (cfg) => localStorage.setItem('ui-morph:demo:llm', JSON.stringify(cfg)),
    { endpoint: 'https://openrouter.ai/api/v1/chat/completions', model: 'deepseek/deepseek-chat', apiKey: KEY },
  )

  // Marta's entry — rich persona for the model to react to
  await page.goto('/index.html?utm_term=laptop+fino+branco', { referer: 'https://google.com/' })
  await page.locator('#morph-consent .yes').click()
  await page.locator('#nova-signin button').click()
  await expect(page.locator('[data-insp="coldpath"]')).toContainText('deepseek/deepseek-chat · live')

  // the prediction loop fires a REAL model call for the next route (C17a)
  await expect
    .poll(async () => (await exchanges(page)).filter((x) => x.returned !== undefined || x.error).length, {
      timeout: 90_000,
      message: 'model call completes during the page life',
    })
    .toBeGreaterThan(0)

  const done = (await exchanges(page)).filter((x) => x.returned !== undefined)
  expect(done.length, `exchanges errored: ${JSON.stringify(await exchanges(page))}`).toBeGreaterThan(0)
  const x = done[done.length - 1]!
  expect(Array.isArray(x.returned), 'model returned a JSON ops array').toBe(true)
  for (const op of x.returned as Record<string, unknown>[]) {
    expect(typeof op.op, 'every proposed item is an op object').toBe('string')
  }

  // the exchange is on camera: sent persona + raw response in the inspector
  await expect(page.locator('[data-insp="coldpath"]')).toContainText('model returned')
  await expect(page.locator('[data-insp="coldpath"]')).toContainText('"traits"')
  await page.locator('[data-insp="coldpath"]').scrollIntoViewIfNeeded()
  await page.locator('[data-insp="coldpath"]').screenshot({ path: `${EV}/live-coldpath.png` })

  // audit recorded the compile; any rejection carries a guard reason
  const trail = await audit(page)
  expect(trail.some((e) => e.kind === 'chain-compiled' && e.detail.includes(x.route))).toBe(true)
  for (const r of trail.filter((e) => e.kind === 'op-rejected')) {
    expect(r.detail.length, 'rejections always carry a reason').toBeGreaterThan(10)
  }

  // navigate into the model-compiled page: ops applied are exactly the
  // guard-accepted ones — the model shaped THIS page load
  await page.getByRole('navigation').getByRole('link', { name: 'Laptops', exact: true }).click()
  await expect(page).toHaveURL(/products/)
  await page.waitForFunction(() => '__audit' in window)
  await expect
    .poll(async () => (await audit(page)).filter((e) => e.kind === 'chain-hit' || e.kind === 'chain-compiled').length, {
      timeout: 30_000,
    })
    .toBeGreaterThan(0)
  const arrival = await audit(page)
  expect(arrival.some((e) => e.kind === 'chain-hit' && e.detail.includes('0 LLM calls'))).toBe(true)
  await page.screenshot({ path: `${EV}/live-applied.png`, fullPage: false })
})
